33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /**
61	     * Pragmatic check for a syntactically valid email address: a non-empty local
62	     * part, a single '@', and a domain with at least one dot-separated label.
63	     */
64	    private static final Pattern EMAIL_PATTERN =
65	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
66	
67	    /**
68	     * Common street-type abbreviations expanded during address normalization,
69	     * keyed by their upper-cased form.
70	     */
71	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
72	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper) {
86	        this.clinicService = clinicService;
87	        this.ownerMapper = ownerMapper;
88	        this.petMapper = petMapper;
89	        this.visitMapper = visitMapper;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        // Validate & normalize the optional email; reject the create when it is present but invalid.
121	        if (!normalizeEmail(ownerFieldsDto)) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
125	        // abbreviations) and store the normalized form back on the DTO so it is what gets
126	        // persisted and compared. Reject the create when the address is blank once normalized.
127	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
128	        if (canonicalAddress.isBlank()) {
129	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
130	        }
131	        ownerFieldsDto.setAddress(canonicalAddress);
132	        // Reject the create when the owner's city is already at capacity, i.e. it already
133	        // contains 50 or more owners (compared case-insensitively).
134	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
138	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
139	        if (normalizedTelephone == null) {
140	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
141	        }
142	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
143	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
144	            .map(Owner::getTelephone)
145	            .map(OwnerRestControllerV1::toE164)
146	            .filter(existing -> existing != null)
147	            .anyMatch(normalizedTelephone::equals);
148	        if (telephoneInUse) {
149	            return new ResponseEntity<>(HttpStatus.CONFLICT);
150	        }
151	        // Reject the create when another owner already shares this owner's last name and address
152	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
153	        // sharing a household.
154	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
155	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
156	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
157	            boolean householdInUse = this.clinicService.findAllOwners().stream()
158	                .anyMatch(existing ->
159	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
160	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
161	            if (householdInUse) {
162	                return new ResponseEntity<>(HttpStatus.CONFLICT);
163	            }
164	        }
165	        ownerFieldsDto.setTelephone(normalizedTelephone);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        // Default the registration date to the server's current date when none was supplied.
169	        if (owner.getRegistrationDate() == null) {
170	            owner.setRegistrationDate(LocalDate.now());
171	        }
172	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
173	        // letters of the city, the upper-cased first three letters of the last name, and a
174	        // per-city 4-digit sequence one greater than the number of owners already in that city.
175	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
176	        // Record how many existing owners already share this owner's first and last name
177	        // (compared case-insensitively) at the moment before this owner is created.
178	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
179	        this.clinicService.saveOwner(owner);
180	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
181	        headers.setLocation(UriComponentsBuilder.newInstance()
182	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
183	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
184	    }
185	
186	    /**
187	     * Validate and normalize the optional owner email in place.
188	     *
189	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
190	     * When present it must be a syntactically valid address; a valid address is
191	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
192	     * present but syntactically invalid, so the caller can reject with 400.
193	     */
194	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
195	        String email = ownerFieldsDto.getEmail();
196	        if (email == null || email.isBlank()) {
197	            ownerFieldsDto.setEmail(null);
198	            return true;
199	        }
200	        String normalized = email.trim().toLowerCase(Locale.ROOT);
201	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
202	            return false;
203	        }
204	        ownerFieldsDto.setEmail(normalized);
205	        return true;
206	    }
207	
208	    /**
209	     * Normalize an owner address: trim, collapse each run of whitespace to a single
210	     * space, upper-case, and expand common street-type abbreviations
211	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
212	     * A {@code null} value normalizes to the empty string.
213	     */
214	    private static String normalizeAddress(String value) {
215	        if (value == null) {
216	            return "";
217	        }
